#include <bits/stdc++.h>
#include "json.hpp"
using namespace std;using J=nlohmann::json;struct E{int k,a,b,c,f,z;};J ld(string p){ifstream f(p);J j;f>>j;return j;}
int main(int ac,char**av){auto st=ld(string(av[1])+"/249-states.json"),sel=ld(string(av[2])+"/COHORT249-SELECTION.json");int n=st["n"],v=st["v"];map<int,int>idx;vector<int>roles;map<int,vector<int>>cuts;for(int i=0;i<(int)sel.size();i++){auto z=sel[i];vector<int>r=z["partners"].get<vector<int>>();r.push_back(z["a"]);for(int x:r)if(!idx.count(x)){idx[x]=roles.size();roles.push_back(x);}cuts[z["cut"].get<int>()].push_back(i);}int W=(roles.size()+63)/64;vector<uint64_t>M((size_t)(n+1)*W);auto row=[&](int s){return &M[(size_t)s*W];};for(int j=0;j<(int)roles.size();j++)row(roles[j])[j/64]|=1ull<<(j%64);ifstream f(string(av[1])+"/249-records.bin",ios::binary);E e;long long equalities=0,identitybits=0,nonzero=0;int maxcut=cuts.rbegin()->first;for(int t=0;t<=maxcut;t++){if(!f.read((char*)&e,sizeof e))throw runtime_error("short stream");if(e.k==1&&(e.c&1))for(int w=0;w<W;w++)row(e.a)[w]^=row(e.b)[w];else if(e.k==2)copy(row(e.a),row(e.a)+W,row(e.b));else if(e.k==3)for(int w=0;w<W;w++)if(row(e.a)[w]!=row(e.b)[w])throw runtime_error("copy prefix mismatch");if(!cuts.count(t))continue;for(int p:cuts[t]){auto z=sel[p];vector<int>r=z["partners"].get<vector<int>>();r.push_back(z["a"]);for(int target=0;target<v;target++){int parity=0;for(int a:r){int c=idx.at(a);parity^=(row(v+target)[c/64]>>(c%64))&1;}if(parity)throw runtime_error("nonzero kernel response at own cut");equalities++;int c=idx.at(z["a"]);nonzero+=(row(v+target)[c/64]>>(c%64))&1;}for(int a:r){int c=idx.at(a);for(int s=0;s<n;s++)if(s<v||s>=2*v){bool bit=(row(s)[c/64]>>(c%64))&1;if(bit!=(s==a))throw runtime_error("non-target prefix influence");identitybits++;}}}}
J receipt={{"status","PASS_INDEPENDENT_MULTI_CUT_FULL_F2_KERNEL_AND_IDENTITY_COLUMNS"},{"cohorts",sel.size()},{"distinct_cuts",cuts.size()},{"distinct_helpers",roles.size()},{"target_kernel_equalities",equalities},{"non_target_identity_bits",identitybits},{"nonzero_pivot_target_entries",nonzero},{"scope","Original pinned-word response at every cohort own cut; combined emitted-word checks remain separate."}};ofstream(av[3])<<receipt.dump(2)<<"\n";cout<<receipt.dump()<<"\n";}
